    from_status_id uuid,
    to_status_id uuid NOT NULL,
    action_type character varying(100) NOT NULL,
    action_by uuid,
    action_role_id uuid,
    action_note text,
    action_datetime timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    pending_reason character varying(100),
    assigned_team_id uuid,
    assigned_user uuid,
    CONSTRAINT chk_action_type CHECK (((action_type)::text = ANY ((ARRAY['SUBMIT'::character varying, 'ASSIGNED'::character varying, 'RESOLVE'::character varying, 'CLOSE'::character varying, 'REJECT'::character varying, 'REOPEN'::character varying])::text[]))),
    CONSTRAINT chk_assigned_team CHECK (((((action_type)::text = 'ASSIGNED'::text) AND (assigned_team_id IS NOT NULL)) OR ((action_type)::text <> 'ASSIGNED'::text))),
    CONSTRAINT chk_pending_reason CHECK (((((action_type)::text = 'PAUSED'::text) AND (pending_reason IS NOT NULL)) OR ((action_type)::text <> 'PAUSED'::text)))
);


ALTER TABLE public.workflow_logs OWNER TO postgres;

